// The Applications list and Add application (docs/51), on the plain server and the database
// e2e/console_server.py seeded for this run, for every role. The organization's admin lands on
// its Applications, adds one, gives the password for its first key, sees the key once, sends
// requests with it as an API client would, and sees them on the list once their minute is
// complete. The others: what they see, and each refused one screen by its address. Then a deep
// link, a session ended on the list and on a key write, and the leak scan with its control. The
// passwords were generated by playwright.config.ts; every key the page issues joins the scan.

import {
  expect,
  test,
  type Browser,
  type Locator,
  type Page,
  type TestInfo,
} from "@playwright/test";
import {
  ADMIN,
  APP_ADMIN,
  APP_READER,
  NO_ROLE,
  NOT_AVAILABLE,
  OPERATOR,
  ORG_READER,
  SESSION_ENDED,
  Scan,
  logIn,
  picture,
  sections,
  type Account,
} from "./session";

test.describe.configure({ mode: "serial" });

// The new application's requests: enough for the error rate to be judged (20, signals.py).
const REQUESTS = 20;

function region(page: Page, name: string): Locator {
  return page.getByRole("region", { name, exact: true });
}

/** The password, if the gateway asks for it (a step-up window may still be open). */
async function confirmIfAsked(page: Page, who: Account, done: Locator): Promise<void> {
  const dialog = page.getByRole("dialog", { name: "Confirm with your password" });
  await expect(dialog.or(done)).toBeVisible();
  if (await dialog.isVisible()) {
    await dialog.getByLabel("Password").fill(process.env[who.second] ?? "");
    await dialog.getByRole("button", { name: "Confirm" }).click();
  }
  await expect(done).toBeVisible();
}

/** Lands where the session lands, and opens `hash` by its address: refused with one sentence. */
async function refusedByAddress(page: Page, hash: string, landing: string): Promise<void> {
  await page.goto(`/dashboard/${hash}`);
  await expect(region(page, landing).getByRole("alert").first()).toHaveText(NOT_AVAILABLE);
}

async function freshPage(browser: Browser, testInfo: TestInfo): Promise<Page> {
  const context = await browser.newContext({
    baseURL: testInfo.project.use.baseURL,
    viewport: { width: 1400, height: 1000 },
  });
  return context.newPage();
}

/** Ends the page's session from another browser holding the same cookie. */
async function endSessionElsewhere(page: Page, browser: Browser, testInfo: TestInfo) {
  const session = (await page.context().cookies()).find((c) => c.name === "gw_session");
  expect(session).toBeDefined();
  const other = await browser.newContext({ baseURL: testInfo.project.use.baseURL });
  if (session !== undefined) await other.addCookies([session]);
  const me = (await (await other.request.get("/v1/auth/me")).json()) as { csrf_token: string };
  const out = await other.request.post("/v1/auth/logout", {
    headers: { "X-CSRF-Token": me.csrf_token },
    data: {},
  });
  expect(out.status()).toBe(200);
  await other.close();
}

test("org admin: lands on Applications, adds one, its key shown once and used, its requests on the list, no leak", async ({
  page,
}, testInfo) => {
  test.setTimeout(240_000);
  const scan = new Scan();
  scan.watch(page);
  await page.goto("/dashboard/");
  await logIn(page, ADMIN, scan);

  const list = region(page, "Applications");
  const table = list.getByRole("table", { name: "Applications" });
  await expect(table.getByRole("row", { name: /App one/ })).toBeVisible();
  await expect(table.getByRole("row", { name: /App two/ })).toBeVisible();
  await expect(list).toContainText("Figures over the last 60 minutes");
  await picture(page, testInfo, "applications-org-admin");

  // Add one: create, then its first key.
  await list.getByRole("link", { name: "Add application" }).click();
  const form = region(page, "Add application");
  await form.getByLabel("Name").fill("E2E shop");
  await form.getByLabel("Plan").selectOption("pro");
  await picture(page, testInfo, "add-application");
  await form.getByRole("button", { name: "Create" }).click();
  await expect(form.getByRole("status")).toContainText("Created E2E shop");
  await form.getByRole("button", { name: "Issue the first key" }).click();
  const shown = region(page, "New API key");
  await confirmIfAsked(page, ADMIN, shown);
  const field = shown.getByLabel("API key");
  const key = await field.inputValue();
  expect(key).toMatch(/^gwk_/);
  scan.remember("issued key", key);
  await expect(shown).toContainText("Shown once. It cannot be shown again.");
  await picture(page, testInfo, "key-shown-once", [field]);
  await shown.getByRole("button", { name: "I have stored it" }).click();
  await expect(shown).toHaveCount(0);
  expect(await page.content()).not.toContain(key);
  await scan.step(page);

  // Its keys, then requests with it as an API client sends them (not through the page).
  await form.getByRole("link", { name: "Its API keys" }).click();
  await expect(page.getByRole("table", { name: "Keys" })).toContainText("first key");
  await picture(page, testInfo, "keys-org-admin");
  for (let i = 0; i < REQUESTS; i++) {
    const answer = await page.request.post("/v1/generate", {
      headers: { Authorization: `Bearer ${key}` },
      data: { model: "economy", prompt: `e2e request ${i.toString()}`, max_tokens: 4 },
    });
    expect(answer.status()).toBe(200);
  }

  // On the list once their minute is complete (25 s after it ends): a state, waited for.
  await sections(page).getByRole("link", { name: "Applications", exact: true }).click();
  const row = table.getByRole("row", { name: /E2E shop/ });
  await expect
    .poll(
      async () => {
        await page.reload();
        await expect(table).toBeVisible();
        return (await row.textContent()) ?? "";
      },
      { timeout: 150_000, intervals: [5_000] },
    )
    .toMatch(new RegExp(`local only${REQUESTS.toString()}0\\.0 %`));
  await picture(page, testInfo, "applications-with-traffic");
  expect(await scan.leaks(page)).toEqual([]);
});

test("org reader: the same list, no Add application and no keys; the Add form by address refused", async ({
  page,
}, testInfo) => {
  const scan = new Scan();
  scan.watch(page);
  await page.goto("/dashboard/");
  await logIn(page, ORG_READER, scan);
  const list = region(page, "Applications");
  await expect(list.getByRole("table", { name: "Applications" })).toContainText("E2E shop");
  await expect(list.getByRole("link", { name: "Add application" })).toHaveCount(0);
  await expect(list.getByRole("link", { name: "API keys" })).toHaveCount(0);
  await picture(page, testInfo, "applications-organization-reader");
  await refusedByAddress(page, "#/apps/new", "Applications");
  await picture(page, testInfo, "hidden-add-organization-reader");
  await refusedByAddress(page, "#/app/app-one/keys", "Applications");
  expect(await scan.leaks(page)).toEqual([]);
});

test("app admin: its application's keys from home; Applications by address refused", async ({
  page,
}, testInfo) => {
  const scan = new Scan();
  scan.watch(page);
  await page.goto("/dashboard/");
  await logIn(page, APP_ADMIN, scan);
  const home = region(page, "Your applications");
  await home.getByRole("link", { name: "API keys" }).click();
  const keys = page.getByRole("table", { name: "Keys" });
  await expect(keys).toContainText("expiring");
  await expect(page.getByRole("form", { name: "Issue a key" })).toBeVisible();
  await picture(page, testInfo, "keys-app-admin");
  await refusedByAddress(page, "#/apps", "Home");
  await refusedByAddress(page, "#/apps/new", "Home");
  await picture(page, testInfo, "hidden-applications-app-admin");
  expect(await scan.leaks(page)).toEqual([]);
});

for (const [who, name] of [
  [APP_READER, "application-reader"],
  [OPERATOR, "platform-admin"],
  [NO_ROLE, "no-role"],
] as const) {
  test(`${name}: no Applications and no keys; each by address refused`, async ({
    page,
  }, testInfo) => {
    const scan = new Scan();
    scan.watch(page);
    await page.goto("/dashboard/");
    await logIn(page, who, scan);
    await expect(sections(page).getByRole("link", { name: "Applications" })).toHaveCount(0);
    await expect(sections(page).getByRole("link", { name: "API keys" })).toHaveCount(0);
    for (const hash of ["#/apps", "#/apps/new", "#/keys", "#/app/app-one/keys"]) {
      await refusedByAddress(page, hash, "Home");
    }
    await picture(page, testInfo, `hidden-applications-${name}`);
    expect(await scan.leaks(page)).toEqual([]);
  });
}

test("a deep link to the Add form from logged out opens it after login", async ({
  browser,
}, testInfo) => {
  const page = await freshPage(browser, testInfo);
  const scan = new Scan();
  scan.watch(page);
  await page.goto("/dashboard/#/apps/new");
  await expect(region(page, "Log in")).toBeVisible();
  await logIn(page, ADMIN, scan);
  await expect(page.getByRole("heading", { name: "Add application", level: 2 })).toBeVisible();
  expect(new URL(page.url()).hash).toBe("#/apps/new");
  expect(await scan.leaks(page)).toEqual([]);
  await page.context().close();
});

test("a session ended on the list, and on a key write, sends the page to login where it was", async ({
  browser,
}, testInfo) => {
  const page = await freshPage(browser, testInfo);
  const scan = new Scan();
  scan.watch(page);
  await page.goto("/dashboard/#/channels");
  await logIn(page, ADMIN, scan);
  await expect(page.getByRole("heading", { name: "Channels", level: 2 })).toBeVisible();
  await endSessionElsewhere(page, browser, testInfo);
  await sections(page).getByRole("link", { name: "Applications", exact: true }).click();
  await expect(region(page, "Log in")).toContainText(SESSION_ENDED);
  expect(new URL(page.url()).hash).toBe("#/apps");
  await picture(page, testInfo, "session-ended-applications");

  // Log in again, open a key form, and lose the session before sending it.
  await logIn(page, ADMIN, scan);
  await page.goto("/dashboard/#/app/app-two/keys");
  const issue = page.getByRole("form", { name: "Issue a key" });
  await issue.getByLabel("Label").fill("late");
  await endSessionElsewhere(page, browser, testInfo);
  await issue.getByRole("button", { name: "Issue a key" }).click();
  await expect(region(page, "Log in")).toContainText(SESSION_ENDED);
  expect(new URL(page.url()).hash).toBe("#/app/app-two/keys");
  await expect(page.getByRole("dialog")).toHaveCount(0);
  expect(await scan.leaks(page)).toEqual([]);
  await page.context().close();
});

test("leak scan control: an issued key planted in storage and in the address is found", async ({
  page,
}) => {
  const scan = new Scan();
  scan.watch(page);
  await page.goto("/dashboard/#/app/app-two/keys");
  await logIn(page, ADMIN, scan);
  const issue = page.getByRole("form", { name: "Issue a key" });
  await issue.getByLabel("Label").fill("control");
  await issue.getByRole("button", { name: "Issue a key" }).click();
  const shown = region(page, "New API key");
  await confirmIfAsked(page, ADMIN, shown);
  const key = await shown.getByLabel("API key").inputValue();
  scan.remember("control key", key);
  await shown.getByRole("button", { name: "I have stored it" }).click();
  expect(await scan.leaks(page)).toEqual([]);

  // Planted by this test, not the page: the key in session storage and in the fragment. The
  // scan must find both, or it could not be trusted to find a leak of a key.
  await page.evaluate((value) => {
    sessionStorage.setItem("planted", value);
    window.location.hash = `#/${encodeURIComponent(value)}`;
  }, key);
  await expect(region(page, "Applications").getByRole("alert").first()).toHaveText(NOT_AVAILABLE);
  const found = await scan.leaks(page);
  expect(found).toContainEqual(["session storage", "control key"]);
  expect(found).toContainEqual(["urls", "control key"]);
  await page.evaluate(() => {
    sessionStorage.removeItem("planted");
  });
});
